std::string generate_rsa_openssh_private_key(int bits) {
    std::string result;
    EVP_PKEY *pkey = nullptr;
    BIO *bio = nullptr;
    OSSL_ENCODER_CTX *ctx = nullptr;
    BUF_MEM *buf = nullptr;

    pkey = EVP_PKEY_Q_keygen(nullptr, nullptr, "RSA", bits);
    if (!pkey) {
        return result;
    }

    bio = BIO_new(BIO_s_mem());
    if (!bio) {
        EVP_PKEY_free(pkey);
        return result;
    }

    ctx = OSSL_ENCODER_CTX_new_for_pkey(pkey, OSSL_KEYMGMT_SELECT_PRIVATE_KEY, "OpenSSH", nullptr, nullptr);
    if (!ctx) {
        BIO_free(bio);
        EVP_PKEY_free(pkey);
        return result;
    }

    if (OSSL_ENCODER_to_bio(ctx, bio)) {
        BIO_get_mem_ptr(bio, &buf);
        if (buf && buf->data && buf->length > 0) {
            result.assign(buf->data, buf->length);
        }
    }

    OSSL_ENCODER_CTX_free(ctx);
    BIO_free(bio);
    EVP_PKEY_free(pkey);

    return result;
}

